INSERT INTO tailor_area (tailor_id, area_id, kind) SELECT t.id, a.id, 'shop_location' FROM tailor t, service_area a WHERE (t.slug, a.slug) IN (('demo-atelier-one','demo-area-a'),('demo-atelier-two','demo-area-b'),('demo-ready-tailor','demo-area-a'));
