INSERT INTO contact_click_daily (tailor_id, channel, date, count) SELECT t.id, 'whatsapp', date('now', '-' || d.n || ' days'), 3 + d.n FROM tailor t, (SELECT 0 AS n UNION SELECT 1 UNION SELECT 2 UNION SELECT 3) d WHERE t.slug IN ('demo-atelier-one','demo-atelier-two');
INSERT INTO contact_click_daily (tailor_id, channel, date, count) SELECT t.id, 'phone', date('now', '-1 days'), 2 FROM tailor t WHERE t.slug = 'demo-atelier-two';
